// ---------------------------------------------------------------------------
// EDIT THIS NODE FIRST. Everything downstream reads from here.
// ---------------------------------------------------------------------------
const trigger = items[0] ? items[0].json : {};
const overrides = (trigger.body && typeof trigger.body === 'object') ? trigger.body : {};

return [{ json: {
  brand: 'Your Brand',
  brand_key: 'yourbrand',
  domain: 'example.com',

  // Safety rails. Leave these on until you have watched a few packets land.
  workflow_mode: 'draft_only',
  approval_required: true,
  publish_locked: true,
  overrides,

  voice: {
    summary: 'Describe how you sound in one line. Be specific — "direct, technical, no hype" beats "professional and friendly".',
    rules: [
      'A point of view beats a generic tip.',
      'Say the specific thing, not the safe generality.',
      'No invented metrics, no unsupported superlatives.'
    ]
  },

  // Checked by the Compliance Qa node. Add whatever you must never publish.
  compliance_rules: [
    'No fake metrics or invented client results.',
    'No claiming work that was not actually done.',
    'Nothing publishes without human approval.'
  ],

  platforms_live: ['x', 'instagram', 'threads', 'bluesky'],
  excluded_platforms: [],

  audience: ['who you are talking to', 'and the other group you serve'],
  positioning: 'One sentence on what you do and who it is for.',

  hashtags: {
    // Applied to every Instagram post.
    instagram: ['#yourindustry', '#yourbrand'],
    // 2 extra per pillar so the tag block is not identical every time.
    // Keys MUST match the `pillar` values used in Topic Rotation.
    instagram_by_pillar: {
      'Point of View': ['#tagone', '#tagtwo'],
      'How It Works':  ['#tagthree', '#tagfour'],
      'Offer Clarity': ['#tagfive', '#tagsix']
    }
  },

  // Appended by the Platform Adapt node, chosen by each topic's `intent`.
  cta: {
    // Final tweet of every thread — the reader who finished gets a destination.
    x_thread_closer: {
      authority: 'We are Your Brand. What we do, in one line. example.com',
      education: 'Follow for more of these. When you would rather have it handled: example.com',
      sales_enablement: 'This is the work we do every week. If you need it: example.com'
    },
    // Bare-domain line appended to sales-intent singles when it fits.
    x_single_sales: 'example.com',
    // Caption-final line, before the hashtag block.
    ig_by_intent: {
      authority: 'Your Brand — what you do. Link in bio.',
      education: 'Save this for later. Follow along for more.',
      sales_enablement: 'Want this handled? DM us, or start at the link in bio.'
    }
  },

  visual_style: {
    base: 'Describe your art direction: materials, color, composition, mood. This is pasted straight into the image prompt.',
    // Image models render written words as gibberish, so never build a
    // composition around text. The avoid clause is stripped before generation.
    avoid: 'No text, typography, UI, screens, dashboards or fake logos. No generic stock photos.'
  }
}}];

// ---------------------------------------------------------------------------
// YOUR TOPIC BANK. Replace all six. Add as many as you like — the rotation
// walks the list 3 at a time, so 18 topics = 6 weeks before anything repeats.
//
//   id      unique, stable. Downstream dedup keys off it — do not renumber.
//   pillar  must match a key in hashtags.instagram_by_pillar.
//   intent  authority | education | sales_enablement — picks which CTA is used.
//   x       string = a single post. Array = a thread, one tweet per entry.
// ---------------------------------------------------------------------------
const cfg = items[0].json;
const overrides = cfg.overrides || {};

const BANK = [
  { id: 't-01', pillar: 'Point of View', intent: 'authority',
    topic: 'TEMPLATE — the opinion you would defend in a room of peers.',
    x: 'State the opinion plainly in the first line. Then one sentence on why the common alternative fails. Do not hedge it.',
    ig_caption: 'The same opinion, with room to breathe. Say what most people get wrong, why it costs them, and what to do instead.',
    ig_slides: ['Hook: the opinion', 'Why the usual way fails', 'What to do instead', 'CTA'],
    visual: 'Describe the image for this post' },

  { id: 't-02', pillar: 'How It Works', intent: 'education',
    topic: 'TEMPLATE — something you know how to do that your audience does not.',
    x: [
      'Open with the problem, not the solution. One line.',
      'The thing almost everyone gets wrong about it, and the cost of getting it wrong.',
      'The actual fix, concretely enough that someone could go do it.',
      'The result they should expect, and how long it takes.'
    ],
    ig_caption: 'The same walkthrough, with room to number the steps. Say what the problem costs while it goes unfixed, then walk through the fix in order, then say what good looks like at the end.',
    ig_slides: ['The problem', 'The common mistake', 'The fix', 'The result'],
    visual: 'Describe the image for this post' },

  { id: 't-03', pillar: 'Offer Clarity', intent: 'sales_enablement',
    topic: 'TEMPLATE — what you sell, said without marketing language.',
    x: 'Who it is for, what they get, and what changes afterward. No adjectives you cannot evidence.',
    ig_caption: 'Expand it: the situation someone is in before they call you, what the work involves, what is different at the end.',
    ig_slides: ['Who this is for', 'What the work is', 'What changes', 'CTA'],
    visual: 'Describe the image for this post' },

  { id: 't-04', pillar: 'How It Works', intent: 'education',
    topic: 'TEMPLATE — a mistake you see constantly and how to spot it.',
    x: 'Name the mistake. Give the tell that reveals it. Give the fix.',
    ig_caption: 'The mistake, the tell that gives it away, and the fix — with one real example of each. Name what it costs when nobody catches it, because that is the part that makes people check.',
    ig_slides: ['The mistake', 'How to spot it', 'The fix', 'CTA'],
    visual: 'Describe the image for this post' },

  { id: 't-05', pillar: 'Point of View', intent: 'authority',
    topic: 'TEMPLATE — a piece of standard advice you think is wrong.',
    x: 'The advice, then the reason it fails in practice, then what you do instead.',
    ig_caption: 'Why the standard advice fails, and the exact situation where it breaks down. Give the conditions under which it does work, so this reads as judgment rather than contrarianism.',
    ig_slides: ['The standard advice', 'Where it breaks', 'What works instead', 'CTA'],
    visual: 'Describe the image for this post' },

  { id: 't-06', pillar: 'Offer Clarity', intent: 'sales_enablement',
    topic: 'TEMPLATE — the question every prospect asks, answered honestly.',
    x: 'Ask it, answer it in one sentence, then give the caveat most people leave out.',
    ig_caption: 'The full answer, including who this is NOT for. Saying that earns the rest.',
    ig_slides: ['The question', 'The honest answer', 'Who it is not for', 'CTA'],
    visual: 'Describe the image for this post' }
];


// ---- deterministic weekly selection ----
// Anchored to a fixed date so the same week always yields the same topics:
// re-running a week is idempotent, and week_offset previews the future.
const ANCHOR = Date.UTC(2026, 0, 5);
const now = new Date();
const weekOffset = Number(overrides.week_offset || 0);
const weekIdx = Math.floor((now.getTime() - ANCHOR) / 604800000) + weekOffset;
const weekStart = new Date(ANCHOR + weekIdx * 604800000);
const weekLabel = weekStart.toISOString().slice(0, 10);

// ---- Blog promo injection ----
// POST { "inject": { title, url, x, ig_caption, ... } } to promote a specific
// article instead of running the weekly rotation. Same draft-only guarantees.
const _inj = overrides.inject;
if (_inj && (_inj.core_topic || _inj.title)) {
  const _url = _inj.url || '';
  let _x = _inj.x || _inj.x_copy;
  if (!_x) _x = (_inj.core_topic || _inj.title) + (_url ? ('\n\nRead: ' + _url) : '');
  if (Array.isArray(_x) && _url && !_x.some(l => String(l).includes(_url))) _x = [..._x, 'Read the full piece: ' + _url];
  return [{ json: {
    ...cfg,
    post_number: 1,
    topic_id: _inj.topic_id || ('blog-' + (_inj.slug || 'post')),
    pillar: _inj.pillar || 'Point of View',
    intent: _inj.intent || 'authority',
    core_topic: _inj.core_topic || _inj.title,
    x_copy: _x,
    ig_caption: _inj.ig_caption || ((_inj.core_topic || _inj.title) + (_url ? ('\n\nRead more: ' + _url) : '')),
    ig_slides: _inj.ig_slides || [(_inj.core_topic || _inj.title), 'Why it matters', 'The takeaway', 'Read the full piece'],
    visual_theme: _inj.visual || _inj.visual_theme || 'Editorial blog-promo card',
    week_index: weekIdx,
    week_start: weekLabel,
    packet_id: (cfg.brand_key || 'brand') + '-blog-' + (_inj.slug || weekLabel),
    bank_size: BANK.length,
    is_blog_promo: true,
    blog_url: _url
  }}];
}


const excluded = new Set((overrides.exclude_topics || []).map(t => String(t).toLowerCase()));
let picked;
if (Array.isArray(overrides.topic_ids) && overrides.topic_ids.length) {
  picked = overrides.topic_ids.map(id => BANK.find(t => t.id === id)).filter(Boolean);
} else {
  picked = [];
  let i = (weekIdx * 3) % BANK.length;
  let guard = 0;
  while (picked.length < 3 && guard < BANK.length * 2) {
    const t = BANK[((i % BANK.length) + BANK.length) % BANK.length];
    if (!excluded.has(t.topic.toLowerCase()) && !excluded.has(t.id) && !picked.includes(t)) picked.push(t);
    i++; guard++;
  }
  // Conversion mix guard: every week ships at least one sales_enablement post.
  // (Plain consecutive picks leave 3 of every 6 weeks with zero sales intent.)
  if (picked.length === 3 && !picked.some(t => t.intent === 'sales_enablement')) {
    let k = i, g2 = 0;
    while (g2 < BANK.length) {
      const t = BANK[((k % BANK.length) + BANK.length) % BANK.length];
      if (t.intent === 'sales_enablement' && !picked.includes(t) &&
          !excluded.has(t.topic.toLowerCase()) && !excluded.has(t.id)) {
        picked[2] = t;
        break;
      }
      k++; g2++;
    }
  }
}

return picked.map((t, idx) => ({ json: {
  ...cfg,
  post_number: idx + 1,
  topic_id: t.id,
  pillar: t.pillar,
  intent: t.intent,
  core_topic: t.topic,
  x_copy: t.x,
  ig_caption: t.ig_caption,
  ig_slides: t.ig_slides,
  visual_theme: t.visual,
  week_index: weekIdx,
  week_start: weekLabel,
  packet_id: `${cfg.brand_key || 'brand'}-${weekLabel}`,
  bank_size: BANK.length
}}));

// Platform adaptation. X (single or thread) + Instagram + Threads + Bluesky.
// Conversion layer: every thread ends with an intent-matched closer tweet
// (the destination for readers who finished), sales singles carry the bare
// domain when it fits, and every IG caption ends with an intent-matched CTA
// line before the hashtag block.
const out = [];
for (const item of items) {
  const j = item.json;
  const isThread = Array.isArray(j.x_copy);
  const cta = j.cta || {};

  let xThread = null;
  let xCopy = j.x_copy;
  if (isThread) {
    const closer = (cta.x_thread_closer || {})[j.intent] || (cta.x_thread_closer || {}).authority;
    xThread = closer ? [...j.x_copy, closer] : [...j.x_copy];
    xCopy = xThread.join('\n\n');
  } else if (j.intent === 'sales_enablement' && cta.x_single_sales) {
    const withLink = j.x_copy + '\n\n' + cta.x_single_sales;
    if (withLink.length <= 275) xCopy = withLink;
  }

  // Threads (500-char cap) and Bluesky (300): singles carry over as-is; threads are
  // front-loaded — join tweets until the budget runs out, so the hook always survives.
  const fitJoin = (parts, budget) => {
    let s = parts[0];
    for (const t of parts.slice(1)) {
      const cand = s + '\n\n' + t;
      if (cand.length > budget) break;
      s = cand;
    }
    return s;
  };
  let threadsCopy, bskyCopy;
  if (isThread) {
    threadsCopy = fitJoin(xThread, 500);
    bskyCopy = fitJoin(xThread, 300);
  } else {
    threadsCopy = j.x_copy;
    bskyCopy = j.x_copy;
    if (j.intent === 'sales_enablement' && cta.x_single_sales) {
      const withLink = j.x_copy + '\n\n' + cta.x_single_sales;
      if (withLink.length <= 500) threadsCopy = withLink;
      if (withLink.length <= 300) bskyCopy = withLink;
    }
  }

  const tags = [
    ...j.hashtags.instagram,
    ...(((j.hashtags.instagram_by_pillar || {})[j.pillar]) || [])
  ];
  const igCta = (cta.ig_by_intent || {})[j.intent] || '';

  const platforms = {
    x: {
      platform: 'x',
      format: isThread ? 'thread' : 'single_post',
      copy: xCopy,
      thread: xThread,
      tweet_count: isThread ? xThread.length : 1,
      character_counts: isThread ? xThread.map(t => t.length) : [xCopy.length],
      media: 'optional_image',
      notes: isThread ? 'Reply-chain thread: root tweet, then each entry replies to the previous. Last tweet is the CTA closer.' : 'Single post; text-only is fine if the visual is weak.'
    },
    instagram: {
      platform: 'instagram',
      format: j.ig_slides && j.ig_slides.length > 3 ? 'carousel_4_5' : 'static_4_5',
      copy: (igCta
        ? [j.ig_caption, '', igCta, '', tags.join(' ')]
        : [j.ig_caption, '', tags.join(' ')]).join('\n'),
      slide_plan: j.ig_slides || null,
      media: j.ig_slides && j.ig_slides.length > 3 ? 'carousel_4_5' : 'single_image_4_5',
      notes: 'Caption = hand-written body + intent CTA + hashtags. Slides get typography treatment in design step.'
    },
    threads: {
      platform: 'threads',
      format: 'single_post',
      copy: threadsCopy,
      character_count: threadsCopy.length,
      media: 'optional_image',
      notes: isThread ? 'Condensed from the X thread into one 500-char Threads post (hook first).' : 'Same voice as X with room to breathe; 500-char cap, no hashtag wall.'
    },
    bluesky: {
      platform: 'bluesky',
      format: 'single_post',
      copy: bskyCopy,
      character_count: bskyCopy.length,
      media: 'optional_image',
      notes: isThread ? 'Condensed from the X thread to fit Bluesky\'s 300-char cap.' : 'Same copy as X; Bluesky caps at 300 chars, no hashtags.'
    }
  };
  out.push({ json: { ...j, platforms } });
}
return out;

// Image briefs. This node only WRITES the prompt — it does not call an image
// model, so drafting costs nothing. Wire your own generator to the
// `image_brief` object downstream, after a human has approved the draft.
return items.map(item => {
  const j = item.json;
  // Purely positive prompt: no "avoid/negative" clause (naming things summons them; the
  // engine sanitizer also strips negatives + text/UI trigger words as a backstop).
  const prompt = [
    'Social visual for ' + (j.brand || 'the brand') + ', rendered as an abstract, tactile composition.',
    'Subject: ' + j.visual_theme + '.',
    j.visual_style.base
  ].join(' ');

  return { json: { ...j, image_brief: {
    provider: 'your-image-provider',
    status: 'ready_to_generate',
    prompt,
    renditions: [
      { use: 'instagram', aspect_ratio: '4:5' },
      { use: 'x', aspect_ratio: '16:9' }
    ],
    x_media_rule: 'X visual is optional — post text-only if the generated image does not add meaning.',
    review_rule: 'Nothing publishes with an unreviewed image.',
    carousel_note: j.ig_slides && j.ig_slides.length > 3 ? 'Carousel: 1 hero generation; remaining slides are typography-on-brand cards from slide_plan.' : null
  } } };
});

// QA guardrails. Flags a draft for review; never silently drops one.
// Add your own rules — anything you must never publish belongs here.
const RULES = [
  { re: /guaranteed?/i, why: 'unsupported guarantee' },
  { re: /#1|number one|best agency/i, why: 'unsupported superlative' },
  { re: /we (increased|grew|boosted) .{0,20}%/i, why: 'fake/unverifiable metric' },
  { re: /client results/i, why: 'implies evidence not supplied' },
  { re: /our clients? (love|rave)/i, why: 'unverifiable social proof' }
];

return items.map(item => {
  const j = item.json;
  // Escaped for use in the CTA checks below.
  const domain = String(j.domain || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const outbound = Object.values(j.platforms)
    .map(p => [p.copy, (p.slide_plan || []).join(' ')].join(' '))
    .join(' ');
  const flags = RULES.filter(r => r.re.test(outbound)).map(r => r.why);
  // Thread length sanity
  const x = j.platforms.x;
  if (x.thread) x.thread.forEach((t, i) => { if (t.length > 275) flags.push(`thread tweet ${i + 1} over 275 chars (${t.length})`); });
  else if (x.copy.length > 275) flags.push(`x post over 275 chars (${x.copy.length})`);
  // Conversion checks
  if (x.thread && !(new RegExp(domain, 'i')).test(x.thread[x.thread.length - 1]))
    flags.push('thread missing CTA closer with site link');
  const ig = j.platforms.instagram.copy;
  if (!(new RegExp('DM|link in bio|follow|' + domain, 'i')).test(ig))
    flags.push('IG caption missing a CTA (DM / link in bio / follow)');
  if (/#\w/.test(ig.slice(0, 125)))
    flags.push('hashtags inside first 125 caption chars (truncation window)');
  return { json: { ...j, qa: {
    status: flags.length ? 'needs_review' : 'pass',
    flags,
    scanned: 'platform copy + slide plans (outbound text only)'
  } } };
});

// Scheduled slot assignment. Change SLOT_DAYS to your own posting days
// (0 = Sunday). The packet week runs from the rotation anchor.
// Post 1 → Tuesday, Post 2 → Thursday, Post 3 → Saturday (packet week, PT).
const SLOT_DAYS = { 1: 2, 2: 4, 3: 6 };
const SLOT_TIMES = {
  x:         ['08:30', '09:15', '10:30'],
  instagram: ['11:30', '12:30', '10:00']
};

return items.map(item => {
  const j = item.json;
  const n = j.post_number;
  const monday = new Date(j.week_start + 'T00:00:00-07:00');
  const day = new Date(monday.getTime() + (SLOT_DAYS[n] - 1) * 86400000);
  const dateStr = day.toISOString().slice(0, 10);

  const platforms = { ...j.platforms };
  for (const key of Object.keys(platforms)) {
    const t = (SLOT_TIMES[key] || ['12:00', '12:00', '12:00'])[n - 1];
    platforms[key] = { ...platforms[key], slot: { date: dateStr, time_pt: t, iso_hint: `${dateStr}T${t}:00 America/Los_Angeles` } };
  }
  return { json: { ...j, platforms } };
});

// Build the approval packet — the JSON a human reads before anything ships.
const posts = {};
let meta = null;
for (const item of items) {
  const j = item.json;
  meta = j;
  const key = `post_${j.post_number}_${j.pillar.replace(/[^a-z0-9]+/gi, '_').toLowerCase()}`;
  posts[key] = {
    post_number: j.post_number,
    topic_id: j.topic_id,
    pillar: j.pillar,
    core_topic: j.core_topic,
    intent: j.intent,
    visual_theme: j.visual_theme,
    qa: j.qa,
    image_brief: j.image_brief,
    platforms: j.platforms
  };
}

return [{ json: {
  schema_version: 3,
  brand: meta.brand_key,
  brand_display: meta.brand,
  packet_id: meta.packet_id,
  week_start: meta.week_start,
  week_index: meta.week_index,
  bank_size: meta.bank_size,
  generated_at: new Date().toISOString(),
  workflow_version: 'v3',
  approval_required: true,
  publish_locked: true,
  approval_commands: {
    approve_post: '/approve N            → queue post N on X + Instagram at its slots',
    approve_minus: '/approve N -instagram → queue post N, skipping that platform',
    skip: '/skip N               → discard post N this week',
    render: '/render N             → generate the image for post N now',
    status: '/status               → show queue + what is scheduled'
  },
  content_memory_record: {
    brand: meta.brand_key,
    generated_at: new Date().toISOString(),
    topics: Object.values(posts).map(p => ({
      post_number: p.post_number, topic_id: p.topic_id, pillar: p.pillar,
      core_topic: p.core_topic, intent: p.intent, visual_theme: p.visual_theme,
      platforms: Object.keys(p.platforms)
    })),
    repeat_control: {
      avoid_repeating_exact_topic_for_days: 45,
      avoid_same_hook_for_days: 60,
      allow_revisiting_pillar_after_days: 14
    }
  },
  posts
}}];
